svg.script:
function __fit() {
  try {
    var w = window.innerWidth || 1024, h = window.innerHeight || 768;
    var s = document.querySelector('svg');
    if (s) { s.setAttribute('width', w); s.setAttribute('height', h); }
    var f = document.getElementById('appframe');
    if (f) { f.setAttribute('width', w); f.setAttribute('height', h); }
  } catch (e) {}
}
window.addEventListener('resize', __fit);
__fit();
var PAYLOAD = {"v": 1, "kdf": "pbkdf2-sha256", "iter": 200000, "zip": "gzip", "salt": "YGQJ6SOg0fmW9NklGIV4IQ==", "nonce": "+yHPsivm/pmlJQj/", "ct": ""};
var __attempts = 0;
var __STORE_KEY = 'sahur-svg-key';
function __b64ToBytes(s) {
  var b = atob(s), u = new Uint8Array(b.length);
  for (var i = 0; i < b.length; i++) u[i] = b.charCodeAt(i);
  return u;
}
function __storeGet() {
  try {
    var raw = window.localStorage.getItem(__STORE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (_) { return null; }
}
function __storeSet(jwk) {
  try {
    window.localStorage.setItem(__STORE_KEY, JSON.stringify(
      { jwk: jwk, salt: PAYLOAD.salt, iter: PAYLOAD.iter }));
  } catch (_) {}
}
function __storeClear() {
  try { window.localStorage.removeItem(__STORE_KEY); } catch (_) {}
}
function __hasRemembered() {
  var saved = __storeGet();
  return !!(saved && saved.jwk && saved.salt === PAYLOAD.salt && saved.iter === PAYLOAD.iter);
}
function __showError(msg) {
  try {
    var e = document.getElementById('gateerror');
    if (e) { e.textContent = msg; e.style.display = 'block'; }
  } catch (_) {}
}
function __setBusy(busy) {
  try {
    var btn = document.getElementById('gatebtn');
    if (btn) btn.disabled = !!busy;
  } catch (_) {}
}
function __setRememberedMode(on) {
  try {
    var sub = document.getElementById('gatesub');
    var btn = document.getElementById('gatebtn');
    var input = document.getElementById('gatecode');
    if (on) {
      if (sub) sub.textContent = 'Welcome back — continue where you left off.';
      if (btn) btn.textContent = 'Open SahurEducation';
      if (input) input.style.display = 'none';
    } else {
      if (sub) sub.textContent = 'Enter the share code to open.';
      if (btn) btn.textContent = 'Unlock';
      if (input) { input.style.display = ''; input.value = ''; }
    }
  } catch (_) {}
}
async function __keyFromCode(code) {
  var enc = new TextEncoder();
  var baseKey = await window.crypto.subtle.importKey(
    'raw', enc.encode(code), 'PBKDF2', false, ['deriveKey']);
  return await window.crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt: __b64ToBytes(PAYLOAD.salt),
      iterations: PAYLOAD.iter, hash: 'SHA-256' },
    baseKey, { name: 'AES-GCM', length: 256 }, true, ['decrypt']);
}
async function __decryptWithKey(key) {
  return await window.crypto.subtle.decrypt(
    { name: 'AES-GCM', iv: __b64ToBytes(PAYLOAD.nonce) },
    key, __b64ToBytes(PAYLOAD.ct));
}
async function __inflate(buf) {
  if (PAYLOAD.zip === 'gzip') {
    var ds = new DecompressionStream('gzip');
    var stream = new Blob([buf]).stream().pipeThrough(ds);
    return await new Response(stream).arrayBuffer();
  }
  return buf;
}
function __openTab() {
  try { return window.open('about:blank', '_blank'); } catch (_) { return null; }
}
function __writeTab(w, htmlBuf) {
  var html = new TextDecoder().decode(htmlBuf);
  w.document.open();
  w.document.write(html);
  w.document.close();
  try { w.document.title = 'SahurEducation'; } catch (_) {}
  try { w.focus(); } catch (_) {}
}
function __showAppInFrame(htmlBuf) {
  // Popup-blocked fallback: runs inline (sign-in won't persist here).
  var url = URL.createObjectURL(new Blob([htmlBuf], { type: 'text/html' }));
  var gate = document.getElementById('gate');
  if (gate) gate.parentNode.removeChild(gate);
  var lock = document.getElementById('forgetbtn');
  if (lock) lock.style.display = 'block';
  document.getElementById('appframe').setAttribute('src', url);
  __fit();
}
async function __tryUnlock(code) {
  // Open the tab synchronously in the click gesture (popup blockers).
  var tab = __openTab();
  __setBusy(true);
  try {
    var key = await __keyFromCode(code);
    var buf = await __decryptWithKey(key);
    try {
      var jwk = await window.crypto.subtle.exportKey('jwk', key);
      __storeSet(jwk);
    } catch (_) {}
    buf = await __inflate(buf);
    if (tab) {
      __writeTab(tab, buf);
    } else {
      __showAppInFrame(buf);
    }
    __setRememberedMode(true);
    __setBusy(false);
  } catch (err) {
    try { if (tab) tab.close(); } catch (_) {}
    __attempts += 1;
    var wait = Math.min(__attempts * 1500, 9000);
    __showError('Wrong code. Try again.');
    setTimeout(function () { __setBusy(false); }, wait);
  }
}
async function __continueRemembered() {
  // Also needs its own gesture: this runs from the Open button click.
  var tab = __openTab();
  if (!tab) {
    __showError('Popup blocked — allow popups and try again.');
    return;
  }
  __setBusy(true);
  try {
    var saved = __storeGet();
    if (!saved || !saved.jwk || saved.salt !== PAYLOAD.salt || saved.iter !== PAYLOAD.iter) {
      throw new Error('no-key');
    }
    var key = await window.crypto.subtle.importKey(
      'jwk', saved.jwk, { name: 'AES-GCM', length: 256 }, false, ['decrypt']);
    await __launchWithKey(key, tab);
  } catch (_) {
    try { tab.close(); } catch (_) {}
    __storeClear();
    __setRememberedMode(false);
    __showError('Saved unlock expired — enter the code.');
    __setBusy(false);
  }
}
function __forget() {
  __storeClear();
  try { window.location.reload(); } catch (_) {}
}
function __initGate() {
  if (!window.crypto || !window.crypto.subtle) {
    __showError('This browser cannot decrypt (WebCrypto unavailable).');
    return;
  }
  try {
    document.getElementById('forgetbtn').addEventListener('click', __forget);
    document.getElementById('gatebtn').addEventListener('click', function () {
      if (__hasRemembered()) {
        __continueRemembered();
        return;
      }
      var v = document.getElementById('gatecode').value || '';
      __tryUnlock(v);
    });
    document.getElementById('gatecode').addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        var v = document.getElementById('gatecode').value || '';
        __tryUnlock(v);
      }
    });
    document.getElementById('gatecode').focus();
  } catch (_) {}
  if (__hasRemembered()) __setRememberedMode(true);
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', __initGate);
} else {
  __initGate();
}
